-- -----------------------------------------------------------------------------
-- 6. Saved searches (the map filters are the source of truth)
-- -----------------------------------------------------------------------------
create table if not exists public.saved_searches (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.users(id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 60),
  filters jsonb not null check (
    jsonb_typeof(filters) = 'object'
    and filters ->> 'category' in ('residential', 'commercial')
  ),
  notify_enabled boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists saved_searches_user_idx on public.saved_searches (user_id);
create index if not exists saved_searches_notify_category_idx
  on public.saved_searches ((filters ->> 'category'))
  where notify_enabled;

alter table public.saved_searches enable row level security;
drop policy if exists "Users read own saved searches" on public.saved_searches;
drop policy if exists "Users insert own saved searches" on public.saved_searches;
drop policy if exists "Users update own saved searches" on public.saved_searches;
drop policy if exists "Users delete own saved searches" on public.saved_searches;
create policy "Users read own saved searches" on public.saved_searches
  for select using (auth.uid() = user_id);
create policy "Users insert own saved searches" on public.saved_searches
  for insert with check (auth.uid() = user_id);
create policy "Users update own saved searches" on public.saved_searches
  for update using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "Users delete own saved searches" on public.saved_searches
  for delete using (auth.uid() = user_id);

create or replace function public.guard_saved_search()
returns trigger
language plpgsql
as $$
declare
  v_count integer;
begin
  new.name := btrim(new.name);
  if tg_op = 'INSERT' then
    perform pg_advisory_xact_lock(hashtext('saved_searches:' || new.user_id::text));
    select count(*) into v_count from public.saved_searches where user_id = new.user_id;
    if v_count >= 10 then
      raise exception 'saved_search_limit' using errcode = 'P0001';
    end if;
    new.created_at := now();
  else
    new.user_id := old.user_id;
    new.created_at := old.created_at;
  end if;
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists guard_saved_search on public.saved_searches;
create trigger guard_saved_search
  before insert or update on public.saved_searches
  for each row execute function public.guard_saved_search();

-- One row per (saved search, new listing). Delivery state lives here.
create table if not exists public.saved_search_matches (
  id uuid primary key default gen_random_uuid(),
  search_id uuid not null references public.saved_searches(id) on delete cascade,
  user_id uuid not null references public.users(id) on delete cascade,
  listing_id uuid not null references public.listings(id) on delete cascade,
  status text not null default 'pending' check (
    status in ('pending', 'sending', 'pushed', 'digest', 'sending_digest', 'digested', 'skipped')
  ),
  matched_at timestamptz not null default now(),
  claimed_at timestamptz,
  delivered_at timestamptz,
  seen_at timestamptz,
  unique (search_id, listing_id)
);

create index if not exists saved_search_matches_status_idx
  on public.saved_search_matches (status, matched_at);
create index if not exists saved_search_matches_user_idx
  on public.saved_search_matches (user_id, matched_at desc);

alter table public.saved_search_matches enable row level security;
drop policy if exists "Users read own saved search matches" on public.saved_search_matches;
create policy "Users read own saved search matches" on public.saved_search_matches
  for select using (auth.uid() = user_id);

create or replace function public.mark_saved_search_seen(p_search_id uuid)
returns void
language sql
security definer
set search_path = public
as $$
  update public.saved_search_matches
  set seen_at = now()
  where search_id = p_search_id and user_id = auth.uid() and seen_at is null;
$$;

revoke all on function public.mark_saved_search_seen(uuid) from public;
grant execute on function public.mark_saved_search_seen(uuid) to authenticated;

-- -----------------------------------------------------------------------------
-- 7. Deterministic matcher — mirrors applyClientFilters() in lib/filters.ts
-- -----------------------------------------------------------------------------
create or replace function public.filter_number(p_value text)
returns numeric
language sql
immutable
as $$
  select case
    when p_value is null then null
    when regexp_replace(p_value, '\s', '', 'g') ~ '^[0-9]+(\.[0-9]+)?$'
      then regexp_replace(p_value, '\s', '', 'g')::numeric
    else null
  end;
$$;

create or replace function public.normalize_property_type(p_value text)
returns text
language sql
immutable
as $$
  select case when p_value = 'condo' then 'condo_strata' else p_value end;
$$;

create or replace function public.listing_matches_saved_search(
  f jsonb,
  l public.listings,
  p_usd_rate numeric
)
returns boolean
language plpgsql
stable
as $$
declare
  v_category text := f ->> 'category';
  v_listing_category text := coalesce(
    l.category::text,
    case when l.type = 'lease' then 'commercial' else 'residential' end
  );
  v_transaction text;
  v_multiplier numeric := case when f ->> 'priceCurrency' = 'USD' then coalesce(p_usd_rate, 12017) else 1 end;
  v_number numeric;
  v_wanted_type text;
  v_listing_type text;
  v_haystack text;
  v_word text;
begin
  -- Drawn-area searches are not matched in V1.
  if jsonb_typeof(f -> 'mapArea') = 'object' then
    return false;
  end if;

  if v_category is distinct from v_listing_category then
    return false;
  end if;

  if v_category = 'residential' then
    v_transaction := nullif(f ->> 'residentialTransaction', '');
    if v_transaction = 'rent' and l.type <> 'rent' then return false; end if;
    if v_transaction = 'sale' and l.type <> 'buy' then return false; end if;
  else
    v_transaction := nullif(f ->> 'commercialTransaction', '');
    if v_transaction = 'lease' and l.type <> 'lease' then return false; end if;
    if v_transaction = 'sale' and l.type <> 'buy' then return false; end if;
  end if;

  v_number := public.filter_number(f ->> 'priceMin');
  if v_number > 0 and l.price < v_number * v_multiplier then return false; end if;
  v_number := public.filter_number(f ->> 'priceMax');
  if v_number > 0 and l.price > v_number * v_multiplier then return false; end if;

  if v_category = 'residential' then
    v_number := public.filter_number(f ->> 'roomsMin');
    if v_number is not null and l.rooms < v_number then return false; end if;

    v_number := public.filter_number(f ->> 'bathroomsMin');
    if v_number is not null and coalesce(l.bathrooms, 0) < v_number then return false; end if;

    if jsonb_typeof(f -> 'views') = 'array' and jsonb_array_length(f -> 'views') > 0 then
      if not (
        coalesce(l.property_views, '{}'::text[])
        && array(select jsonb_array_elements_text(f -> 'views'))
      ) then
        return false;
      end if;
    end if;

    if nullif(f ->> 'level', '') is not null and l.level is distinct from f ->> 'level' then
      return false;
    end if;
  end if;

  v_number := public.filter_number(f ->> 'areaMin');
  if v_number is not null and l.area_m2 < v_number then return false; end if;
  v_number := public.filter_number(f ->> 'areaMax');
  if v_number is not null and l.area_m2 > v_number then return false; end if;

  v_listing_type := public.normalize_property_type(coalesce(
    l.property_type,
    case when v_listing_category = 'residential' then 'residential' else 'office' end
  ));

  v_wanted_type := nullif(nullif(f ->> 'propertyType', ''), 'any');
  if v_wanted_type is not null and v_listing_type is distinct from public.normalize_property_type(v_wanted_type) then
    return false;
  end if;

  v_number := public.filter_number(f ->> 'yearBuiltMin');
  if v_number is not null and coalesce(l.year_built, 0) < v_number then return false; end if;
  v_number := public.filter_number(f ->> 'yearBuiltMax');
  if v_number is not null and coalesce(l.year_built, 9999) > v_number then return false; end if;

  if btrim(coalesce(f ->> 'keywords', '')) <> '' then
    v_haystack := lower(coalesce(l.description, '') || ' ' || l.district || ' ' || coalesce(v_listing_type, ''));
    for v_word in
      select w from regexp_split_to_table(lower(btrim(f ->> 'keywords')), '\s+') as w where w <> ''
    loop
      if position(v_word in v_haystack) = 0 then
        return false;
      end if;
    end loop;
  end if;

  if jsonb_typeof(f -> 'districts') = 'array' and jsonb_array_length(f -> 'districts') > 0 then
    if not (l.district in (select jsonb_array_elements_text(f -> 'districts'))) then
      return false;
    end if;
  end if;

  -- listedSinceDays is irrelevant: only brand-new listings are matched.
  return true;
end;
$$;

-- Finds new listings (with photos, or 30 min old) and records matches.
create or replace function public.enqueue_saved_search_matches(p_limit integer default 200)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_rate numeric;
  v_listing public.listings%rowtype;
  v_category text;
  v_inserted integer;
  v_total integer := 0;
begin
  select uzs_per_unit into v_rate from public.fx_rates where currency = 'USD';

  for v_listing in
    select l.*
    from public.listings l
    where l.search_matched_at is null
      and l.status = 'active'
      and l.posted_at <= now() - interval '2 minutes'
      and (
        exists (select 1 from public.listing_photos p where p.listing_id = l.id)
        or l.posted_at <= now() - interval '30 minutes'
      )
    order by l.posted_at
    limit p_limit
    for update of l skip locked
  loop
    v_category := coalesce(
      v_listing.category::text,
      case when v_listing.type = 'lease' then 'commercial' else 'residential' end
    );

    insert into public.saved_search_matches (search_id, user_id, listing_id)
    select s.id, s.user_id, v_listing.id
    from public.saved_searches s
    where s.notify_enabled
      and s.filters ->> 'category' = v_category
      and s.user_id <> v_listing.user_id
      and public.listing_matches_saved_search(s.filters, v_listing, v_rate)
    on conflict (search_id, listing_id) do nothing;

    get diagnostics v_inserted = row_count;
    v_total := v_total + v_inserted;

    update public.listings set search_matched_at = now() where id = v_listing.id;
  end loop;

  return v_total;
end;
$$;

-- Atomically claims matches for delivery. Matches whose search was switched off
-- or whose listing is no longer active are marked 'skipped' instead.
-- p_mode: 'instant' (pending -> sending) or 'digest' (digest -> sending_digest).
-- Dropped first: patch-alerts-v1.sql adds a column to the result (re-running must not fail).
drop function if exists public.claim_saved_search_matches(text, integer);
create or replace function public.claim_saved_search_matches(p_mode text, p_limit integer default 500)
returns table (
  match_id uuid,
  search_id uuid,
  search_name text,
  user_id uuid,
  listing_id uuid,
  listing_district text,
  locale text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_from text;
  v_to text;
begin
  if p_mode = 'instant' then
    v_from := 'pending'; v_to := 'sending';
  elsif p_mode = 'digest' then
    v_from := 'digest'; v_to := 'sending_digest';
  else
    raise exception 'unknown mode %', p_mode;
  end if;

  -- Recover rows stuck mid-delivery (e.g. the function crashed) after 15 minutes.
  update public.saved_search_matches m
  set status = v_from, claimed_at = null
  where m.status = v_to and m.claimed_at < now() - interval '15 minutes';

  update public.saved_search_matches m
  set status = 'skipped', delivered_at = now()
  where m.status = v_from
    and (
      not exists (select 1 from public.saved_searches s where s.id = m.search_id and s.notify_enabled)
      or not exists (select 1 from public.listings l where l.id = m.listing_id and l.status = 'active')
    );

  return query
  with picked as (
    select m.id
    from public.saved_search_matches m
    where m.status = v_from
    order by m.matched_at
    limit p_limit
    for update skip locked
  ),
  claimed as (
    update public.saved_search_matches m
    set status = v_to, claimed_at = now()
    from picked
    where m.id = picked.id
    returning m.id, m.search_id, m.user_id, m.listing_id
  )
  select c.id, c.search_id, s.name, c.user_id, c.listing_id, l.district,
         coalesce(np.locale, 'uz')
  from claimed c
  join public.saved_searches s on s.id = c.search_id
  join public.listings l on l.id = c.listing_id
  left join public.notification_preferences np on np.user_id = c.user_id;
end;
$$;

revoke all on function public.enqueue_saved_search_matches(integer) from public, anon, authenticated;
revoke all on function public.claim_saved_search_matches(text, integer) from public, anon, authenticated;
revoke all on function public.listing_matches_saved_search(jsonb, public.listings, numeric) from public, anon, authenticated;
grant execute on function public.enqueue_saved_search_matches(integer) to service_role;
grant execute on function public.claim_saved_search_matches(text, integer) to service_role;
grant execute on function public.listing_matches_saved_search(jsonb, public.listings, numeric) to service_role;

-- >>>>>>>>>>>>>>>> patch-listing-integrity-v1.sql <<<<<<<<<<<<<<<<
-- =============================================================================
-- Reyeltor-uz: listing integrity — duplicate detection at publication
-- =============================================================================
-- Run AFTER patch-saved-searches-v1.sql. Safe to re-run.
--
-- The app calls find_similar_own_listings() before publishing. If the user already
-- has an active listing that looks like the same property, the app offers to update
-- it instead. It never blocks: similar-but-different properties (two flats in the
-- same building) can still be published.
-- =============================================================================

create or replace function public.find_similar_own_listings(
  p_type listing_type,
  p_category text,
  p_property_type text,
  p_price integer,
  p_area_m2 integer,
  p_lat float8,
  p_lng float8,
  p_rooms smallint default null
)
returns table (
  id uuid,
  price integer,
  area_m2 integer,
  rooms smallint,
  district text,
  posted_at timestamptz,
  distance_m float8
)
language sql
stable
security invoker
set search_path = public
as $$
  with candidates as (
    select
      l.id, l.price, l.area_m2, l.rooms, l.district, l.posted_at,
      -- Haversine distance in metres.
      6371000 * 2 * asin(least(1, sqrt(
        power(sin(radians(l.lat - p_lat) / 2), 2)
        + cos(radians(p_lat)) * cos(radians(l.lat)) * power(sin(radians(l.lng - p_lng) / 2), 2)
      ))) as distance_m
    from public.listings l
    where l.user_id = auth.uid()
      and l.status = 'active'
      and l.type = p_type
      and coalesce(l.category::text, case when l.type = 'lease' then 'commercial' else 'residential' end) = p_category
      and (
        p_property_type is null
        or public.normalize_property_type(coalesce(l.property_type, p_property_type))
           = public.normalize_property_type(p_property_type)
      )
      and (p_rooms is null or p_rooms = 0 or l.rooms = p_rooms)
      -- Same size within 7% (min 3 m²) and price within 15%: owners re-post with small changes.
      and abs(l.area_m2 - p_area_m2) <= greatest(3, p_area_m2 * 0.07)
      and abs(l.price - p_price) <= p_price * 0.15
  )
  select c.id, c.price, c.area_m2, c.rooms, c.district, c.posted_at, c.distance_m
  from candidates c
  where c.distance_m <= 150
  order by c.distance_m, c.posted_at desc
  limit 3;
$$;

revoke all on function public.find_similar_own_listings(listing_type, text, text, integer, integer, float8, float8, smallint) from public, anon;
grant execute on function public.find_similar_own_listings(listing_type, text, text, integer, integer, float8, float8, smallint) to authenticated;

-- >>>>>>>>>>>>>>>> patch-seller-tools-v1.sql <<<<<<<<<<<<<<<<
-- =============================================================================
-- Reyeltor-uz: seller tools — listing performance tracking
-- =============================================================================
-- Run AFTER patch-saved-searches-v1.sql and patch-listing-integrity-v1.sql. Safe to re-run.
--
-- * listing_events stores views (app + public web page), contact taps and shares.
--   Nobody can read or write it directly; only through the two functions below.
-- * record_listing_event(): counts an event at most once per viewer per 30 minutes,
--   never counts the owner's own activity, and only for active listings.
-- * get_listing_performance(): aggregated numbers for the listing's owner only.
-- =============================================================================

create table if not exists public.listing_events (
  id bigint generated always as identity primary key,
  listing_id uuid not null references public.listings(id) on delete cascade,
  event_type text not null check (event_type in ('view', 'web_view', 'contact_call', 'contact_message', 'share')),
  viewer_key text not null check (char_length(viewer_key) between 8 and 80),
  user_id uuid references public.users(id) on delete set null,
  created_at timestamptz not null default now()
);

create index if not exists listing_events_listing_idx
  on public.listing_events (listing_id, created_at desc);
create index if not exists listing_events_dedup_idx
  on public.listing_events (listing_id, event_type, viewer_key, created_at desc);

alter table public.listing_events enable row level security;
-- Intentionally no policies: access only via the security definer functions below.

create or replace function public.record_listing_event(
  p_listing_id uuid,
  p_event text,
  p_viewer_key text
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_owner uuid;
  v_uid uuid := auth.uid();
begin
  if p_event is null or p_event not in ('view', 'web_view', 'contact_call', 'contact_message', 'share') then
    return false;
  end if;
  if p_viewer_key is null or char_length(p_viewer_key) not between 8 and 80 then
    return false;
  end if;

  select user_id into v_owner from public.listings where id = p_listing_id and status = 'active';
  if not found then
    return false;
  end if;

  -- The owner looking at or sharing their own listing is not audience interest.
  if v_uid is not null and v_uid = v_owner then
    return false;
  end if;

  if exists (
    select 1 from public.listing_events
    where listing_id = p_listing_id
      and event_type = p_event
      and viewer_key = p_viewer_key
      and created_at > now() - interval '30 minutes'
  ) then
    return false;
  end if;

  insert into public.listing_events (listing_id, event_type, viewer_key, user_id)
  values (p_listing_id, p_event, p_viewer_key, v_uid);

  if p_event in ('view', 'web_view') then
    update public.listings set view_count = coalesce(view_count, 0) + 1 where id = p_listing_id;
  end if;

  return true;
end;
$$;

revoke all on function public.record_listing_event(uuid, text, text) from public;
grant execute on function public.record_listing_event(uuid, text, text) to anon, authenticated;

create or replace function public.get_listing_performance(p_listing_id uuid)
returns table (
  views integer,
  unique_viewers integer,
  views_7d integer,
  web_views integer,
  contact_taps integer,
  contacts_7d integer,
  shares integer,
  favorites integer,
  favorites_7d integer,
  days_published integer,
  tracking_since timestamptz
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not exists (
    select 1 from public.listings where id = p_listing_id and user_id = auth.uid()
  ) then
    raise exception 'not_listing_owner' using errcode = '42501';
  end if;

  return query
  select
    coalesce(l.view_count, 0)::integer,
    (select count(distinct e.viewer_key) from public.listing_events e
      where e.listing_id = l.id and e.event_type in ('view', 'web_view'))::integer,
    (select count(*) from public.listing_events e
      where e.listing_id = l.id and e.event_type in ('view', 'web_view')
        and e.created_at > now() - interval '7 days')::integer,
    (select count(*) from public.listing_events e
      where e.listing_id = l.id and e.event_type = 'web_view')::integer,
    (select count(*) from public.listing_events e
      where e.listing_id = l.id and e.event_type in ('contact_call', 'contact_message'))::integer,
    (select count(*) from public.listing_events e
      where e.listing_id = l.id and e.event_type in ('contact_call', 'contact_message')
        and e.created_at > now() - interval '7 days')::integer,
    (select count(*) from public.listing_events e
      where e.listing_id = l.id and e.event_type = 'share')::integer,
    (select count(*) from public.favorites f where f.listing_id = l.id)::integer,
    (select count(*) from public.favorites f
      where f.listing_id = l.id and f.saved_at > now() - interval '7 days')::integer,
    greatest(0, floor(extract(epoch from (now() - l.posted_at)) / 86400))::integer,
    (select min(e.created_at) from public.listing_events e where e.listing_id = l.id)
  from public.listings l
  where l.id = p_listing_id;
end;
$$;

revoke all on function public.get_listing_performance(uuid) from public, anon;
grant execute on function public.get_listing_performance(uuid) to authenticated;

-- >>>>>>>>>>>>>>>> patch-privacy-v1.sql <<<<<<<<<<<<<<<<
-- =============================================================================
-- Reyeltor-uz: profile privacy
-- =============================================================================
-- Run AFTER the other -v1 patches. Safe to re-run.
--
-- Problem: the "Users are publicly readable" policy let anyone download every user's
-- full row — phone numbers (even when "show phone" is off), emails, coin balances.
--
-- Fix:
--   * users: each person can read only their own full row.
--   * public_profiles: what buyers may see about a seller. Phone only when the seller
--     chose to show it; only people who have published at least one listing appear.
--
-- Note: app builds <= 1.2.2 read seller details straight from users, so after this patch
-- they will not show the seller card on other people's listings until users update.
-- =============================================================================

drop policy if exists "Users are publicly readable" on public.users;
drop policy if exists "Users read own profile" on public.users;
create policy "Users read own profile" on public.users
  for select using (auth.uid() = id);

alter table public.users add column if not exists email_visible boolean not null default true;

-- Runs with the owner's rights (not security_invoker) so it can show other sellers,
-- but only the columns listed here.
create or replace view public.public_profiles
with (security_barrier = true)
as
select
  u.id,
  u.full_name,
  u.avatar_url,
  u.bio,
  u.telegram_username,
  -- Email is shown to buyers as a contact unless the seller hides it in Profile.
  case when u.email_visible then u.email else null end as email,
  case when u.phone_visible then u.phone else null end as phone,
  u.phone_visible,
  u.total_posted,
  u.total_rented,
  u.total_sold,
  u.total_expired,
  u.avg_days_on_market,
  u.close_rate,
  u.created_at,
  u.last_active_at,
  u.email_visible
from public.users u
where exists (select 1 from public.listings l where l.user_id = u.id);

revoke all on public.public_profiles from public;
grant select on public.public_profiles to anon, authenticated;

-- >>>>>>>>>>>>>>>> patch-freshness-v1.sql <<<<<<<<<<<<<<<<
-- =============================================================================
-- Reyeltor-uz: listing freshness
-- =============================================================================
-- Run AFTER the other -v1 patches. Safe to re-run.
--
-- * availability_confirmed_at: when the owner last confirmed the property is still
--   available. Set by the server only: on publication, on reactivation, and through
--   confirm_listing_available(). The phone cannot write it directly.
-- * Confirming also renews the 90-day expiry, so actively confirmed listings stay up and
--   unconfirmed ones expire.
-- * archive_expired_listings(): archives listings past their expiry. Called by the daily
--   notification-jobs function (the old pg_cron example in schema.sql was commented out,
--   so expired listings were never archived).
-- =============================================================================

do $$
begin
  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'listings' and column_name = 'availability_confirmed_at'
  ) then
    alter table public.listings add column availability_confirmed_at timestamptz;
    -- Existing listings: treat the last edit (or publication) as the last confirmation.
    update public.listings set availability_confirmed_at = coalesce(last_edited_at, posted_at, now());
  end if;
end $$;

-- Server-owned column: set on insert, kept on client updates (except reactivation).
create or replace function public.guard_availability_confirmed()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'INSERT' then
    if reyeltor_private.is_app_user() or new.availability_confirmed_at is null then
      new.availability_confirmed_at := now();
    end if;
    return new;
  end if;

  if reyeltor_private.is_app_user() and pg_trigger_depth() = 1 then
    if new.status = 'active' and old.status is distinct from 'active' then
      new.availability_confirmed_at := now(); -- reactivating = confirming
    else
      new.availability_confirmed_at := old.availability_confirmed_at;
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists guard_availability_confirmed on public.listings;
create trigger guard_availability_confirmed
  before insert or update on public.listings
  for each row execute function public.guard_availability_confirmed();

create or replace function public.confirm_listing_available(p_listing_id uuid)
returns timestamptz
language plpgsql
security definer
set search_path = public
as $$
declare
  v_confirmed timestamptz := now();
begin
  update public.listings
  set availability_confirmed_at = v_confirmed,
      expires_at = v_confirmed + interval '90 days'
  where id = p_listing_id
    and user_id = auth.uid()
    and status = 'active';

  if not found then
    raise exception 'listing_not_confirmable' using errcode = 'P0001';
  end if;
  return v_confirmed;
end;
$$;

revoke all on function public.confirm_listing_available(uuid) from public, anon;
grant execute on function public.confirm_listing_available(uuid) to authenticated;

create or replace function public.archive_expired_listings()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  update public.listings
  set status = 'archived',
      archived_reason = 'expired',
      archived_at = now(),
      deletes_at = now() + interval '30 days'
  where status = 'active' and expires_at < now();
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

revoke all on function public.archive_expired_listings() from public, anon, authenticated;
grant execute on function public.archive_expired_listings() to service_role;

-- The public listing page and seller cards may show the freshness date.
-- (Listings are already publicly readable; nothing else to grant.)

-- >>>>>>>>>>>>>>>> patch-hardening-v1.sql <<<<<<<<<<<<<<<<
-- =============================================================================
-- Reyeltor-uz: security hardening (audit fixes)
-- =============================================================================
-- Run AFTER the other -v1 patches (included in apply-all-v1.sql). Safe to re-run.
--
-- 1. Reports (flags): only signed-in users, one report per account per listing, and
--    a listing is auto-archived only after 3 DIFFERENT accounts (not the owner, each
--    at least 1 day old) report it. Before: anyone could send 3 reports with made-up
--    device ids and take any listing down.
-- 2. Photo storage: users can upload, replace and delete files only in folders of
--    their own listings (avatars keep their own per-user rules). Before: any signed-in
--    user could overwrite or delete anyone's photos.
-- 3. Account deletion: delete_my_account() really deletes the account (auth user,
--    profile, listings, favorites, coins, searches). Before: RLS silently blocked
--    deleting the profile, so "Delete all data" left the account in place.
-- 4. purge_deleted_listings(): removes archived listings 30 days after archiving,
--    as the app promises. Called by the daily notification-jobs function, which
--    first removes their photo files from storage.
-- 5. Email visibility: sellers can hide their email from buyers (users.email_visible).
-- 6. is_phone_registered(): lets sign-up say "this phone is already registered" before
--    creating the account (otherwise Supabase only reports "Database error saving new user").
-- 7. Ratings tables (if installed): no self-ratings, review reports private, reporter recorded.
-- =============================================================================

-- 1. Reports ------------------------------------------------------------------
drop policy if exists "Anyone can flag listings" on public.flags;
drop policy if exists "Signed-in users can report listings" on public.flags;
create policy "Signed-in users can report listings" on public.flags
  for insert with check (auth.uid() is not null and user_id = auth.uid());

do $$
begin
  if not exists (select 1 from pg_indexes where indexname = 'flags_listing_user_uniq') then
    begin
      create unique index flags_listing_user_uniq on public.flags (listing_id, user_id) where user_id is not null;
    exception when unique_violation then
      raise notice 'flags_listing_user_uniq not created: existing duplicate reports. Clean them up and re-run.';
    end;
  end if;
end $$;

create or replace function public.check_flag_count()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_owner uuid;
  v_reporters integer;
begin
  select user_id into v_owner from listings where id = new.listing_id;

  select count(distinct f.user_id) into v_reporters
  from flags f
  join users u on u.id = f.user_id
  where f.listing_id = new.listing_id
    and f.user_id is not null
    and f.user_id is distinct from v_owner
    and u.created_at < now() - interval '1 day';

  if v_reporters >= 3 then
    update listings set status = 'archived', archived_reason = 'manually_archived',
      archived_at = now(), deletes_at = now() + interval '30 days'
    where id = new.listing_id and status = 'active';
  end if;
  return new;
end;
$$;

create index if not exists flags_listing_idx on public.flags (listing_id);

-- 2. Photo storage --------------------------------------------------------------
drop policy if exists "Authenticated upload reyeltor listings bucket" on storage.objects;
drop policy if exists "Authenticated update reyeltor listings bucket" on storage.objects;
drop policy if exists "Authenticated delete reyeltor listings bucket" on storage.objects;
drop policy if exists "Owners upload listing photos" on storage.objects;
drop policy if exists "Owners update listing photos" on storage.objects;
drop policy if exists "Owners delete listing photos" on storage.objects;

-- Listing photos live at "<listing id>/<file>". Text comparison avoids cast errors on other folders.
create policy "Owners upload listing photos" on storage.objects
  for insert with check (
    bucket_id = 'reyeltor-listings'
    and exists (
      select 1 from public.listings l
      where l.id::text = (storage.foldername(name))[1] and l.user_id = auth.uid()
    )
  );
create policy "Owners update listing photos" on storage.objects
  for update using (
    bucket_id = 'reyeltor-listings'
    and exists (
      select 1 from public.listings l
      where l.id::text = (storage.foldername(name))[1] and l.user_id = auth.uid()
    )
  );
create policy "Owners delete listing photos" on storage.objects
  for delete using (
    bucket_id = 'reyeltor-listings'
    and exists (
      select 1 from public.listings l
      where l.id::text = (storage.foldername(name))[1] and l.user_id = auth.uid()
    )
  );

-- 3. Account deletion -------------------------------------------------------------
create or replace function public.delete_my_account()
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;
  -- Cascades: users -> listings (-> photos rows, price history, flags, matches, events),
  -- favorites, coin ledger, check-ins, saved searches, push tokens, notification rows.
  delete from auth.users where id = v_uid;
end;
$$;

revoke all on function public.delete_my_account() from public, anon;
grant execute on function public.delete_my_account() to authenticated;

-- 4. Purge archived listings after their 30-day grace period --------------------
create or replace function public.purge_deleted_listings(p_limit integer default 500)
returns table (listing_id uuid, storage_path text)
language plpgsql
security definer
set search_path = public
as $$
begin
  return query
  with doomed as (
    select l.id from public.listings l
    where l.status = 'archived' and l.deletes_at is not null and l.deletes_at < now()
    order by l.deletes_at
    limit p_limit
  ),
  photos as (
    select p.listing_id, p.storage_path
    from public.listing_photos p
    join doomed d on d.id = p.listing_id
  ),
  gone as (
    delete from public.listings l using doomed d where l.id = d.id returning l.id
  )
  select ph.listing_id, ph.storage_path from photos ph;
end;
$$;

revoke all on function public.purge_deleted_listings(integer) from public, anon, authenticated;
grant execute on function public.purge_deleted_listings(integer) to service_role;

-- Foreign-key indexes Postgres does not create automatically (map, detail and favorites queries).
create index if not exists listings_status_idx on public.listings (status);
create index if not exists listings_user_status_idx on public.listings (user_id, status);
create index if not exists listing_photos_listing_idx on public.listing_photos (listing_id);
create index if not exists favorites_listing_idx on public.favorites (listing_id);
create index if not exists price_history_listing_idx on public.price_history (listing_id);

-- 5. Email visibility ------------------------------------------------------------
alter table public.users add column if not exists email_visible boolean not null default true;

create or replace view public.public_profiles
with (security_barrier = true)
as
select
  u.id,
  u.full_name,
  u.avatar_url,
  u.bio,
  u.telegram_username,
  case when u.email_visible then u.email else null end as email,
  case when u.phone_visible then u.phone else null end as phone,
  u.phone_visible,
  u.total_posted,
  u.total_rented,
  u.total_sold,
  u.total_expired,
  u.avg_days_on_market,
  u.close_rate,
  u.created_at,
  u.last_active_at,
  u.email_visible
from public.users u
where exists (select 1 from public.listings l where l.user_id = u.id);

revoke all on public.public_profiles from public;
grant select on public.public_profiles to anon, authenticated;

-- 6. Phone availability for sign-up ---------------------------------------------
create or replace function public.is_phone_registered(p_phone text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select length(regexp_replace(coalesce(p_phone, ''), '\D', '', 'g')) >= 9
     and exists (
       select 1 from public.users u
       where right(regexp_replace(u.phone, '\D', '', 'g'), 9) = right(regexp_replace(p_phone, '\D', '', 'g'), 9)
     );
$$;
revoke all on function public.is_phone_registered(text) from public;
grant execute on function public.is_phone_registered(text) to anon, authenticated;

-- 7. Ratings (optional feature; only if migrations/002 was applied) ----------------
do $$
begin
  if to_regclass('public.ratings') is not null then
    drop policy if exists "Users can create their own ratings" on public.ratings;
    create policy "Users can create their own ratings" on public.ratings
      for insert with check (
        auth.uid() = user_id
        and target_id <> auth.uid()
        and not exists (
          select 1 from public.listings l where l.id = target_id and l.user_id = auth.uid()
        )
      );
    drop policy if exists "Users can update their own ratings" on public.ratings;
    create policy "Users can update their own ratings" on public.ratings
      for update using (auth.uid() = user_id)
      with check (auth.uid() = user_id and target_id <> auth.uid());
  end if;

  if to_regclass('public.review_reports') is not null then
    alter table public.review_reports add column if not exists reporter_id uuid references auth.users(id) on delete set null default auth.uid();
    drop policy if exists "Anyone can view review reports" on public.review_reports;
    drop policy if exists "Reporters can view own review reports" on public.review_reports;
    create policy "Reporters can view own review reports" on public.review_reports
      for select using (reporter_id = auth.uid());
    drop policy if exists "Users can create review reports" on public.review_reports;
    create policy "Users can create review reports" on public.review_reports
      for insert with check (auth.uid() is not null and reporter_id = auth.uid());
  end if;
end $$;

-- >>>>>>>>>>>>>>>> patch-telegram-auth-v1.sql <<<<<<<<<<<<<<<<
-- =============================================================================
-- Reyeltor-uz: Telegram-verified registration + phone/password login
-- =============================================================================
-- Run AFTER the other -v1 patches (included in apply-all-v1.sql). Safe to re-run.
--
-- Registration now goes through the Telegram bot (supabase/functions/telegram-auth):
--   1. The app opens t.me/<bot>?start=<code>; the user taps "Share phone number" in the bot.
--      Telegram sends the bot the user's own phone number and name.
--   2. They choose a password; email is optional.
--   3. The server creates the account. Accounts without an email get an internal,
--      undeliverable sign-in address "tg<telegram id>@telegram.reyeltor.invalid" which is
--      never shown to anyone (the profile email stays empty).
-- Login: phone + password or email + password (checked by auth_password_login below).
-- Forgot password: re-confirm with Telegram, or the email reset link if an email is set.
--
-- This patch:
--   * users.email becomes optional; adds users.telegram_id and users.phone_verified_at
--   * app users cannot change telegram_id / phone_verified_at, or a Telegram-verified phone
--   * telegram_auth_flows: short-lived server-only state for each Telegram confirmation
--   * auth_login_attempts + auth_password_login(): password check with brute-force limits
--   * find_user_by_phone(): server-only phone lookup used by the function
-- =============================================================================

-- Placeholder sign-in addresses for accounts registered without an email.
create schema if not exists reyeltor_private;
create or replace function reyeltor_private.is_placeholder_email(p_email text)
returns boolean
language sql
immutable
as $$
  select coalesce(lower(p_email) like '%@telegram.reyeltor.invalid', false)
$$;

-- 1. Profile columns ------------------------------------------------------------
alter table public.users alter column email drop not null;
alter table public.users add column if not exists telegram_id bigint;
alter table public.users add column if not exists phone_verified_at timestamptz;
create unique index if not exists users_telegram_id_key on public.users (telegram_id) where telegram_id is not null;
-- Phone lookups by digits (login, duplicate checks).
create index if not exists users_phone_digits_idx on public.users ((regexp_replace(phone, '\D', '', 'g')));
create index if not exists users_email_lower_idx on public.users ((lower(email)));

-- Placeholder addresses never reach the profile.
update public.users set email = null where reyeltor_private.is_placeholder_email(email);

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_email text := case when reyeltor_private.is_placeholder_email(new.email) then null else new.email end;
begin
  insert into public.users (id, full_name, phone, email, phone_visible, coin_balance)
  values (
    new.id,
    coalesce(nullif(trim(new.raw_user_meta_data->>'full_name'), ''), nullif(split_part(coalesce(v_email, ''), '@', 1), ''), 'User'),
    coalesce(new.raw_user_meta_data->>'phone', ''),
    v_email,
    coalesce((new.raw_user_meta_data->>'phone_visible')::boolean, true),
    15
  )
  on conflict (id) do nothing;

  insert into public.notification_preferences (user_id, locale)
  values (new.id, coalesce(nullif(new.raw_user_meta_data->>'locale', ''), 'en'))
  on conflict (user_id) do nothing;

  if not exists (
    select 1 from public.coin_transactions
    where user_id = new.id and type = 'welcome'
  ) then
    insert into public.coin_transactions (user_id, amount, type)
    values (new.id, 15, 'welcome');
  end if;

  return new;
end;
$$;

-- Verified identity is set by the server only.
create or replace function public.guard_user_verified_identity()
returns trigger
language plpgsql
as $$
begin
  if not reyeltor_private.is_app_user() or pg_trigger_depth() > 1 then
    return new;
  end if;
  if tg_op = 'INSERT' then
    new.telegram_id := null;
    new.phone_verified_at := null;
  else
    new.telegram_id := old.telegram_id;
    new.phone_verified_at := old.phone_verified_at;
    -- A Telegram-verified phone can only change through a new Telegram confirmation.
    if old.phone_verified_at is not null then
      new.phone := old.phone;
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists guard_user_verified_identity on public.users;
create trigger guard_user_verified_identity
  before insert or update on public.users
  for each row execute function public.guard_user_verified_identity();

-- 2. Telegram confirmation flows (server-only) -----------------------------------
create table if not exists public.telegram_auth_flows (
  id uuid primary key default gen_random_uuid(),
  purpose text not null check (purpose in ('register', 'reset')),
  secret_hash text not null,
  start_code text not null unique,
  locale text not null default 'uz',
  status text not null default 'pending'
    check (status in ('pending', 'verified', 'phone_taken', 'no_phone', 'not_registered', 'cancelled', 'failed', 'consumed')),
  telegram_id bigint,
  telegram_username text,
  phone text,
  first_name text,
  last_name text,
  user_id uuid references auth.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '15 minutes',
  completed_at timestamptz
);
create index if not exists telegram_auth_flows_tg_idx on public.telegram_auth_flows (telegram_id, created_at desc);
create index if not exists telegram_auth_flows_expires_idx on public.telegram_auth_flows (expires_at);
alter table public.telegram_auth_flows enable row level security;
revoke all on public.telegram_auth_flows from anon, authenticated;

-- 3. Phone lookup (server-only) ----------------------------------------------------
-- Matches "+998 90 123-45-67", "998901234567" and "901234567" (Uzbek local) alike.
create or replace function public.find_user_by_phone(p_phone text)
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  with d as (select regexp_replace(coalesce(p_phone, ''), '\D', '', 'g') as digits)
  select u.id
  from public.users u, d
  where length(d.digits) >= 9
    and regexp_replace(u.phone, '\D', '', 'g') in (d.digits, case when length(d.digits) = 9 then '998' || d.digits end)
  order by u.phone_verified_at desc nulls last, u.created_at
  limit 1
$$;
revoke all on function public.find_user_by_phone(text) from public, anon, authenticated;
grant execute on function public.find_user_by_phone(text) to service_role;

-- is_phone_registered (patch-hardening) now uses the same matching.
create or replace function public.is_phone_registered(p_phone text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.find_user_by_phone(p_phone) is not null
$$;
revoke all on function public.is_phone_registered(text) from public;
grant execute on function public.is_phone_registered(text) to anon, authenticated;

-- 4. Password login with brute-force limits (server-only) ------------------------
create table if not exists public.auth_login_attempts (
  id bigint generated always as identity primary key,
  identifier text not null,
  ip text,
  success boolean not null,
  attempted_at timestamptz not null default now()
);
create index if not exists auth_login_attempts_identifier_idx on public.auth_login_attempts (identifier, attempted_at desc);
create index if not exists auth_login_attempts_ip_idx on public.auth_login_attempts (ip, attempted_at desc);
alter table public.auth_login_attempts enable row level security;
revoke all on public.auth_login_attempts from anon, authenticated;

-- Returns the user id when the password is right. Never raises for bad input, so the
-- attempt row is always kept. Status: ok | invalid_credentials | too_many_attempts.
create or replace function public.auth_password_login(p_identifier text, p_password text, p_ip text default null)
returns table (user_id uuid, status text)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_raw text := trim(coalesce(p_identifier, ''));
  v_is_email boolean := position('@' in v_raw) > 0;
  v_key text;
  v_user uuid;
  v_ok boolean := false;
begin
  v_key := case when v_is_email then lower(v_raw) else regexp_replace(v_raw, '\D', '', 'g') end;
  if length(v_key) = 9 and not v_is_email then
    v_key := '998' || v_key;
  end if;

  if (select count(*) from public.auth_login_attempts a
      where a.identifier = v_key and not a.success and a.attempted_at > now() - interval '15 minutes') >= 5
     or (p_ip is not null and (select count(*) from public.auth_login_attempts a
      where a.ip = p_ip and not a.success and a.attempted_at > now() - interval '15 minutes') >= 30) then
    return query select null::uuid, 'too_many_attempts'::text;
    return;
  end if;

  if v_is_email then
    select u.id into v_user from public.users u where lower(u.email) = v_key limit 1;
    if v_user is null then
      select au.id into v_user from auth.users au where lower(au.email) = v_key limit 1;
    end if;
  elsif length(v_key) >= 9 then
    v_user := public.find_user_by_phone(v_key);
  end if;

  if v_user is not null and coalesce(p_password, '') <> '' then
    select coalesce(au.encrypted_password = extensions.crypt(p_password, au.encrypted_password), false)
      into v_ok
    from auth.users au
    where au.id = v_user
      and coalesce(au.encrypted_password, '') <> ''
      and (au.banned_until is null or au.banned_until < now());
    v_ok := coalesce(v_ok, false);
  end if;

  insert into public.auth_login_attempts (identifier, ip, success) values (v_key, p_ip, v_ok);
  -- Housekeeping: keep a day of history.
  delete from public.auth_login_attempts where attempted_at < now() - interval '1 day';

  if v_ok then
    return query select v_user, 'ok'::text;
  else
    return query select null::uuid, 'invalid_credentials'::text;
  end if;
end;
$$;
revoke all on function public.auth_password_login(text, text, text) from public, anon, authenticated;
grant execute on function public.auth_password_login(text, text, text) to service_role;

-- >>>>>>>>>>>>>>>> patch-alerts-v1.sql <<<<<<<<<<<<<<<<
-- =============================================================================
-- Reyeltor-uz: last-search alerts + price-drop alerts for favorites
-- =============================================================================
-- Run AFTER the other -v1 patches (included in apply-all-v1.sql). Safe to re-run.
--
-- 1. Last search: the filters a signed-in user last searched with on the map are kept as
--    one hidden saved search (kind = 'last'). It runs through the same matcher, daily cap
--    and digest as saved searches, does not count toward the 10-search limit, and can be
--    muted or saved permanently from Favorites → Searches.
-- 2. Price drops: each favorite remembers a reference price (alert_price, the price when
--    it was saved or last alerted). When the listing becomes at least 3% cheaper than that,
--    the owner of the favorite gets one push; the reference then moves to the new price.
--    Price increases raise the reference silently, so "cheaper than before" is what counts.
-- =============================================================================

-- 1. Last search ----------------------------------------------------------------
alter table public.saved_searches add column if not exists kind text not null default 'saved';
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'saved_searches_kind_valid') then
    alter table public.saved_searches
      add constraint saved_searches_kind_valid check (kind in ('saved', 'last'));
  end if;
end $$;
create unique index if not exists saved_searches_one_last_per_user
  on public.saved_searches (user_id) where kind = 'last';

create or replace function public.guard_saved_search()
returns trigger
language plpgsql
as $$
declare
  v_count integer;
begin
  new.name := btrim(new.name);
  if tg_op = 'INSERT' then
    if new.kind = 'saved' then
      perform pg_advisory_xact_lock(hashtext('saved_searches:' || new.user_id::text));
      select count(*) into v_count from public.saved_searches where user_id = new.user_id and kind = 'saved';
      if v_count >= 10 then
        raise exception 'saved_search_limit' using errcode = 'P0001';
      end if;
    end if;
    new.created_at := now();
  else
    new.user_id := old.user_id;
    new.created_at := old.created_at;
    -- "Save" turns the last search into a normal saved search (counts toward the limit).
    if old.kind = 'last' and new.kind = 'saved' then
      perform pg_advisory_xact_lock(hashtext('saved_searches:' || new.user_id::text));
      select count(*) into v_count from public.saved_searches where user_id = new.user_id and kind = 'saved';
      if v_count >= 10 then
        raise exception 'saved_search_limit' using errcode = 'P0001';
      end if;
    elsif new.kind is distinct from old.kind then
      new.kind := old.kind;
    end if;
  end if;
  new.updated_at := now();
  return new;
end;
$$;

/**
 * Remembers the user's latest map search. Returns the last-search id, or null when the
 * same filters are already a saved search (that one alerts already; no duplicate pushes).
 * Changing the filters drops alerts still queued for the previous filters.
 */
create or replace function public.set_last_search(p_filters jsonb, p_name text)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
  v_old jsonb;
begin
  if v_uid is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;
  if jsonb_typeof(p_filters) <> 'object' or p_filters ->> 'category' not in ('residential', 'commercial') then
    raise exception 'invalid_filters' using errcode = '22023';
  end if;

  if exists (select 1 from public.saved_searches where user_id = v_uid and kind = 'saved' and filters = p_filters) then
    delete from public.saved_searches where user_id = v_uid and kind = 'last';
    return null;
  end if;

  select id, filters into v_id, v_old from public.saved_searches where user_id = v_uid and kind = 'last';
  if v_id is null then
    insert into public.saved_searches (user_id, name, filters, kind)
    values (v_uid, left(coalesce(nullif(btrim(p_name), ''), 'Last search'), 60), p_filters, 'last')
    returning id into v_id;
  elsif v_old is distinct from p_filters then
    update public.saved_searches
    set filters = p_filters, name = left(coalesce(nullif(btrim(p_name), ''), 'Last search'), 60)
    where id = v_id;
    delete from public.saved_search_matches where search_id = v_id and status in ('pending', 'digest');
  end if;
  return v_id;
end;
$$;
revoke all on function public.set_last_search(jsonb, text) from public, anon;
grant execute on function public.set_last_search(jsonb, text) to authenticated;

-- The delivery job needs to know which matches come from the last search (different text).
drop function if exists public.claim_saved_search_matches(text, integer);
create or replace function public.claim_saved_search_matches(p_mode text, p_limit integer default 500)
returns table (
  match_id uuid,
  search_id uuid,
  search_name text,
  search_kind text,
  user_id uuid,
  listing_id uuid,
  listing_district text,
  locale text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_from text;
  v_to text;
begin
  if p_mode = 'instant' then
    v_from := 'pending'; v_to := 'sending';
  elsif p_mode = 'digest' then
    v_from := 'digest'; v_to := 'sending_digest';
  else
    raise exception 'unknown mode %', p_mode;
  end if;

  update public.saved_search_matches m
  set status = v_from, claimed_at = null
  where m.status = v_to and m.claimed_at < now() - interval '15 minutes';

  update public.saved_search_matches m
  set status = 'skipped', delivered_at = now()
  where m.status = v_from
    and (
      not exists (select 1 from public.saved_searches s where s.id = m.search_id and s.notify_enabled)
      or not exists (select 1 from public.listings l where l.id = m.listing_id and l.status = 'active')
    );

  -- A listing matching both a saved search and the last search is pushed once (saved wins).
  update public.saved_search_matches m
  set status = 'skipped', delivered_at = now()
  from public.saved_searches s
  where m.status = v_from and s.id = m.search_id and s.kind = 'last'
    and exists (
      select 1 from public.saved_search_matches o
      join public.saved_searches os on os.id = o.search_id and os.kind = 'saved'
      where o.user_id = m.user_id and o.listing_id = m.listing_id
    );

  return query
  with picked as (
    select m.id
    from public.saved_search_matches m
    where m.status = v_from
    order by m.matched_at
    limit p_limit
    for update skip locked
  ),
  claimed as (
    update public.saved_search_matches m
    set status = v_to, claimed_at = now()
    from picked
    where m.id = picked.id
    returning m.id, m.search_id, m.user_id, m.listing_id
  )
  select c.id, c.search_id, s.name, s.kind, c.user_id, c.listing_id, l.district,
         coalesce(np.locale, 'uz')
  from claimed c
  join public.saved_searches s on s.id = c.search_id
  join public.listings l on l.id = c.listing_id
  left join public.notification_preferences np on np.user_id = c.user_id;
end;
$$;
revoke all on function public.claim_saved_search_matches(text, integer) from public, anon, authenticated;
grant execute on function public.claim_saved_search_matches(text, integer) to service_role;

-- 2. Price drops on favorites ----------------------------------------------------
alter table public.favorites add column if not exists alert_price numeric;
update public.favorites f
set alert_price = l.price
from public.listings l
where l.id = f.listing_id and f.alert_price is null;

-- Not security definer: app users may read listings anyway, and is_app_user() must see them.
create or replace function public.set_favorite_alert_price()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if tg_op = 'INSERT' then
    select price into new.alert_price from public.listings where id = new.listing_id;
  elsif reyeltor_private.is_app_user() then
    new.alert_price := old.alert_price; -- only the server moves the reference price
  end if;
  return new;
end;
$$;

drop trigger if exists set_favorite_alert_price on public.favorites;
create trigger set_favorite_alert_price
  before insert or update on public.favorites
  for each row execute function public.set_favorite_alert_price();

/**
 * Favorites whose listing is now at least p_min_drop cheaper than the reference price.
 * Moves each returned favorite's reference to the current price (so one drop = one push)
 * and raises references silently when prices went up. Server-only.
 */
create or replace function public.claim_price_drop_alerts(p_min_drop numeric default 0.03, p_limit integer default 1000)
returns table (
  user_id uuid,
  listing_id uuid,
  old_price numeric,
  new_price numeric,
  listing_district text,
  listing_type text,
  locale text,
  favorites_enabled boolean
)
language plpgsql
security definer
set search_path = public
as $$
begin
  -- Price went up: follow it, so a later drop is measured from the higher price.
  update public.favorites f
  set alert_price = l.price
  from public.listings l
  where l.id = f.listing_id and l.status = 'active' and f.alert_price is not null and l.price > f.alert_price;

  return query
  with drops as (
    select f.id as favorite_id, f.user_id, f.listing_id, f.alert_price as old_price, l.price::numeric as new_price,
           l.district, l.type::text as listing_type
    from public.favorites f
    join public.listings l on l.id = f.listing_id
    where l.status = 'active'
      and l.user_id <> f.user_id
      and f.alert_price is not null
      and l.price <= f.alert_price * (1 - p_min_drop)
    order by f.id
    limit p_limit
    for update of f skip locked
  ),
  moved as (
    update public.favorites f
    set alert_price = d.new_price
    from drops d
    where f.id = d.favorite_id
    returning f.id
  )
  select d.user_id, d.listing_id, d.old_price, d.new_price, d.district, d.listing_type,
         coalesce(np.locale, 'uz'), coalesce(np.favorites_enabled, true)
  from drops d
  join moved m on m.id = d.favorite_id
  left join public.notification_preferences np on np.user_id = d.user_id;
end;
$$;
revoke all on function public.claim_price_drop_alerts(numeric, integer) from public, anon, authenticated;
grant execute on function public.claim_price_drop_alerts(numeric, integer) to service_role;

commit;
